import logging
from .file_getter import FileGetter

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class SshFileGetter(FileGetter):
    """
    FileGetter interface for SSHConnection/ProxySSHConnection.
    """

    def __init__(self, managed_ssh_connection, **kwargs):
        """
        Create an SSH file getter.

        :param ManagedSshConnection managed_ssh_connection: managed SSH connection
        """

        super(SshFileGetter, self).__init__(**kwargs)
        self._managed_ssh_connection = managed_ssh_connection
        self.add_prerequisite(managed_ssh_connection)

    def get_file(self, source_path, target_path):
        logger.debug(
            "getting {source_path!r} from {host!r} as {user!r} into {target_path!r}".format(
                host=self._managed_ssh_connection.host,
                user=self._managed_ssh_connection.user,
                source_path=source_path,
                target_path=target_path))
        try:
            self._managed_ssh_connection.files.get(
                remote_path=source_path,
                local_path=target_path)
        except Exception as exception:
            logger.debug("getting file failed with %r, trying to get file again", exception)
            self._managed_ssh_connection.teardown(group=self._group, force=True)
            self._managed_ssh_connection.setup(group=self._group)
            self._managed_ssh_connection.files.get(
                remote_path=source_path,
                local_path=target_path)
